import itertools

def count_overlaps(A, B):
    count = 0
    for i in A:
        for j in B:
            if max(i[0], j[0]) <= min(i[1], j[1]):
                count += 1
    return count

def is_valid(schedule, k):
    endpoints = []
    for i in schedule:
        endpoints.append(i[0])
        endpoints.append(i[1])
    endpoints = sorted(list(set(endpoints)))
    for i in range(len(endpoints) - 1):
        mid = (endpoints[i] + endpoints[i+1]) / 2
        if sum(1 for start, end in schedule if start <= mid <= end) > k:
            return False
    for p in endpoints:
        if sum(1 for start, end in schedule if start <= p <= end) > k:
            return False
    return True

def find_max_overlaps(N, k):
    # We only need to check intervals with endpoints in {0, 1, ..., 2*N}
    possible_intervals = []
    for s in range(2*N + 1):
        for e in range(s, 2*N + 1):
            possible_intervals.append((s, e))

    # This is still too many. Let's restrict to a smaller set of intervals.
    # Let's try to find the best schedule A and then the best schedule B.
    # For a fixed A, the best B is the one that maximizes overlaps.
    # But we can just pick A = { [0, 1] * k, ... } no.
    # Let's try A = { [0, 2] * 2, [3, 5] * 2 } for N=4, k=2.
    A = [(0, 2), (0, 2), (3, 5), (3, 5)]
    best_n = 0

    # Now we search for B
    # B is a set of 4 intervals from possible_intervals such that is_valid(B, 2)
    # This is still too many. Let's use a heuristic or a smaller search space.
    # The best B will likely use intervals that are also simple.
    simple_intervals = [(0, 2), (3, 5), (1, 4), (0, 5), (2, 3), (0, 1), (4, 5)]
    for B in itertools.product(simple_intervals, repeat=N):
        if is_valid(B, k):
            best_n = max(best_n, count_overlaps(A, B))
    return best_n

