def find_max_overlaps(N, k):
    # Use a more diverse set of A's
    best_overall = 0
    simple_intervals = [(0, 1), (1, 2), (2, 3), (3, 4), (0, 2), (1, 3), (2, 4), (0, 3), (1, 4), (0, 4)]
    for A in itertools.product(simple_intervals, repeat=N):
        if is_valid(A, k):
            # Now find best B
            best_for_A = 0
            for B in itertools.product(simple_intervals, repeat=N):
                if is_valid(B, k):
                    best_for_A = max(best_for_A, count_overlaps(A, B))
            best_overall = max(best_overall, best_for_A)
    return best_overall

